macro_rules! deps {
    () => {
        DFA!();
        State!();
        NFA!();
    };
}

macro_rules! LiteralTrie {
    () => {
        deps!();
        # [doc = " A trie that preserves leftmost-first match semantics."] # [doc = ""] # [doc = " This is a purpose-built data structure for optimizing 'lit1|lit2|..|litN'"] # [doc = " patterns. It can *only* handle alternations of literals, which makes it"] # [doc = " somewhat restricted in its scope, but literal alternations are fairly"] # [doc = " common."] # [doc = ""] # [doc = " At a 5,000 foot level, the main idea of this trie is make an alternation of"] # [doc = " literals look more like a DFA than an NFA via epsilon removal."] # [doc = ""] # [doc = " More precisely, the main issue is in how alternations are compiled into"] # [doc = " a Thompson NFA. Namely, each alternation gets a single NFA \"union\" state"] # [doc = " with an epsilon transition for every branch of the alternation pointing to"] # [doc = " an NFA state corresponding to the start of that branch. The main problem"] # [doc = " with this representation is the cost of computing an epsilon closure. Once"] # [doc = " you hit the alternation's start state, it acts as a sort of \"clog\" that"] # [doc = " requires you to traverse all of the epsilon transitions to compute the full"] # [doc = " closure."] # [doc = ""] # [doc = " While fixing such clogs in the general case is pretty tricky without going"] # [doc = " to a DFA (or perhaps a Glushkov NFA, but that comes with other problems)."] # [doc = " But at least in the case of an alternation of literals, we can convert"] # [doc = " that to a prefix trie without too much cost. In theory, that's all you"] # [doc = " really need to do: build the trie and then compile it to a Thompson NFA."] # [doc = " For example, if you have the pattern 'bar|baz|foo', then using a trie, it"] # [doc = " is transformed to something like 'b(a(r|z))|f'. This reduces the clog by"] # [doc = " reducing the number of epsilon transitions out of the alternation's start"] # [doc = " state from 3 to 2 (it actually gets down to 1 when you use a sparse state,"] # [doc = " which we do below). It's a small effect here, but when your alternation is"] # [doc = " huge, the savings is also huge."] # [doc = ""] # [doc = " And that is... essentially what a LiteralTrie does. But there is one"] # [doc = " hiccup. Consider a regex like 'sam|samwise'. How does a prefix trie compile"] # [doc = " that when leftmost-first semantics are used? If 'sam|samwise' was the"] # [doc = " entire regex, then you could just drop the 'samwise' branch entirely since"] # [doc = " it is impossible to match ('sam' will always take priority, and since it"] # [doc = " is a prefix of 'samwise', 'samwise' will never match). But what about the"] # [doc = " regex '\\b(sam|samwise)\\b'? In that case, you can't remove 'samwise' because"] # [doc = " it might match when 'sam' doesn't fall on a word boundary."] # [doc = ""] # [doc = " The main idea is that 'sam|samwise' can be translated to 'sam(?:|wise)',"] # [doc = " which is a precisely equivalent regex that also gets rid of the clog."] # [doc = ""] # [doc = " Another example is 'zapper|z|zap'. That gets translated to"] # [doc = " 'z(?:apper||ap)'."] # [doc = ""] # [doc = " We accomplish this by giving each state in the trie multiple \"chunks\" of"] # [doc = " transitions. Each chunk barrier represents a match. The idea is that once"] # [doc = " you know a match occurs, none of the transitions after the match can be"] # [doc = " re-ordered and mixed in with the transitions before the match. Otherwise,"] # [doc = " the match semantics could be changed."] # [doc = ""] # [doc = " See the 'State' data type for a bit more detail."] # [doc = ""] # [doc = " Future work:"] # [doc = ""] # [doc = " * In theory, it would be nice to generalize the idea of removing clogs and"] # [doc = " apply it to the NFA graph itself. Then this could in theory work for"] # [doc = " case insensitive alternations of literals, or even just alternations where"] # [doc = " each branch starts with a non-epsilon transition."] # [doc = " * Could we instead use the Aho-Corasick algorithm here? The aho-corasick"] # [doc = " crate deals with leftmost-first matches correctly, but I think this implies"] # [doc = " encoding failure transitions into a Thompson NFA somehow. Which seems fine,"] # [doc = " because failure transitions are just unconditional epsilon transitions?"] # [doc = " * Or perhaps even better, could we use an aho_corasick::AhoCorasick"] # [doc = " directly? At time of writing, 0.7 is the current version of the"] # [doc = " aho-corasick crate, and that definitely cannot be used as-is. But if we"] # [doc = " expose the underlying finite state machine API, then could we use it? That"] # [doc = " would be super. If we could figure that out, it might also lend itself to"] # [doc = " more general composition of finite state machines."] # [derive (Clone)] pub (crate) struct LiteralTrie { # [doc = " The set of trie states. Each state contains one or more chunks, where"] # [doc = " each chunk is a sparse set of transitions to other states. A leaf state"] # [doc = " is always a match state that contains only empty chunks (i.e., no"] # [doc = " transitions)."] states : Vec < State > , # [doc = " Whether to add literals in reverse to the trie. Useful when building"] # [doc = " a reverse NFA automaton."] rev : bool , }
    };
}

LiteralTrie!()